\begin{aligned}
\hat b_k^{(1)}
&=\frac{1}{\sqrt{2\sinh\!\left(\dfrac{\pi\omega}{a}\right)}}
\left(
e^{\pi\omega/2a}\hat c_k^{(1)}
+e^{-\pi\omega/2a}\hat c_{-k}^{(2)\dagger}
